#include <Arduino.h>
#include <TM1637Display.h>

TM1637Display display(4, 5);
struct Button {
  uint8_t pin;
  int raw;
  int stable;
  unsigned long changed;
};
Button addButton = {2, HIGH, HIGH, 0};
Button startButton = {3, HIGH, HIGH, 0};
unsigned long remaining = 0;
unsigned long lastTick = 0;
unsigned long alarmStarted = 0;
bool running = false;
bool alarming = false;

bool pressed(Button &b, unsigned long now) {
  int level = digitalRead(b.pin);
  if (level != b.raw) {
    b.raw = level;
    b.changed = now;
  }
  if (b.stable != b.raw && now - b.changed >= 30) {
    b.stable = b.raw;
    return b.stable == LOW;
  }
  return false;
}

void showRemaining() {
  display.showNumberDec((int)min(remaining, 9999UL), false);
}

void beginAlarm(unsigned long now) {
  running = false;
  alarming = true;
  alarmStarted = now;
  tone(6, 1000);
}

void setup() {
  pinMode(2, INPUT_PULLUP);
  pinMode(3, INPUT_PULLUP);
  pinMode(6, OUTPUT);
  noTone(6);
  display.setBrightness(7);
  showRemaining();
}

void loop() {
  unsigned long now = millis();
  bool add = pressed(addButton, now);
  bool start = pressed(startButton, now);
  if (add) {
    remaining += 10;
    showRemaining();
  }
  if (start && !running && !alarming) {
    lastTick = now;
    if (remaining == 0) beginAlarm(now);
    else running = true;
  }
  if (running) {
    unsigned long elapsedSeconds = (now - lastTick) / 1000UL;
    if (elapsedSeconds > 0) {
      lastTick += elapsedSeconds * 1000UL;
      if (elapsedSeconds >= remaining) {
        remaining = 0;
        showRemaining();
        beginAlarm(now);
      } else {
        remaining -= elapsedSeconds;
        showRemaining();
      }
    }
  }
  if (alarming && now - alarmStarted >= 2000UL) {
    noTone(6);
    alarming = false;
  }
}
